#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_stack_to_string_buffer_too_small_for_comma_and_space(void) {
    /* Path 5 conditions:
     * - buffer != NULL
     * - buffer_size > 0
     * - ptr != NULL && ptr->top != -1 (non-empty stack)
     * - buffer_size >= 3 (passed the empty stack check)
     * - Loop enters (i <= ptr->top && remaining > 0)
     * - For i > 0 (second element), (remaining < 2) is true -> break
     * - Then (remaining >= 1) is true -> writes ']'
     * - Returns written
     *
     * We need a stack with at least 2 elements, and a buffer that can hold
     * the opening '[' and the first number, but not the ", " before the second.
     * Example: stack [42, 99], buffer size just enough for "[42" (4 chars).
     * After writing '[', remaining = 3.
     * Write "42" (2 chars) -> remaining = 1.
     * i becomes 1, i>0 true, remaining < 2 true -> break.
     * remaining >= 1 true -> writes ']'.
     * Result: "[42]" (4 chars written).
     */
    DArrayStack *stack = create_stack(5);
    TEST_ASSERT_NOT_NULL(stack);
    int push_result;
    push_result = push(stack, 42);
    TEST_ASSERT_EQUAL_INT(0, push_result);
    push_result = push(stack, 99);
    TEST_ASSERT_EQUAL_INT(1, push_result);

    /* Buffer size calculation:
     * We need at least 3 for empty stack check.
     * We want to fit "[42]" which is 4 characters plus null terminator = 5.
     * But we want to trigger the break when trying to add ", " before second element.
     * After writing '[', remaining = buffer_size - 1.
     * Write "42" (2 chars) -> remaining = buffer_size - 3.
     * For break condition (remaining < 2) we need buffer_size - 3 < 2 -> buffer_size < 5.
     * Choose buffer_size = 4.
     * Then:
     * - buffer_size >= 3 true
     * - remaining initial = 3
     * - Write '[' -> remaining = 2
     * - Write "42" -> remaining = 0
     * - i becomes 1, i>0 true, remaining < 2 true -> break
     * - remaining >= 1 false -> does NOT write ']'
     * Wait, that's a different path (remaining >= 1 false).
     * We need remaining >= 1 true after the break.
     * So we need remaining >= 1 after writing the number.
     * That means buffer_size - 3 >= 1 -> buffer_size >= 4.
     * And remaining < 2 for the comma/space check -> buffer_size - 3 < 2 -> buffer_size < 5.
     * So buffer_size must be exactly 4.
     * Then:
     * - remaining after writing '[' = 3
     * - Write "42" -> remaining = 1
     * - i=1, i>0 true, remaining < 2 true -> break
     * - remaining >= 1 true -> writes ']'
     * Total written: '[', '4', '2', ']' = 4.
     */
    char buffer[5]; /* size 4 + 1 for null terminator in test */
    int buffer_size = 4;
    int result = stack_to_string(stack, buffer, buffer_size);

    TEST_ASSERT_EQUAL_INT(4, result);
    TEST_ASSERT_EQUAL_STRING("[42]", buffer);

    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_stack_to_string_buffer_too_small_for_comma_and_space);
    return UNITY_END();
}

